// Temporary pre-merge contract. Remove alongside auto-qa-smoke.lock.yml.
const assert = require("node:assert/strict");
const { createHash } = require("node:crypto");
const { readFileSync } = require("node:fs");
const { join } = require("node:path");
const { test } = require("node:test");
const read = (file) =>
  readFileSync(join(__dirname, "../workflows", file), "utf8");
const normal = read("auto-qa.lock.yml");
const harnessFile = "auto-qa-smoke.lock.yml";
const harness = read(harnessFile);
const hash = (text) => createHash("sha256").update(text).digest("hex");
const changes = [
  [
    "# This file was automatically generated by gh-aw (v1.2.2). DO NOT EDIT.",
    "# TEMPORARY PRE-MERGE TEST HARNESS: remove before requesting review/merging.\n# Derived from auto-qa.lock.yml at 48fd16da2e737336e77742e4231ed738e05e7eaf.\n# Only the test envelope and immutable metadata-source checkout differ.\n# Original generation notice: This file was automatically generated by gh-aw (v1.2.2). DO NOT EDIT.",
  ],
  ['name: "Auto QA"\non:', 'name: "Auto QA smoke test (temporary)"\non:'],
  [
    '  group: auto-qa-${{ github.event.pull_request.number }}\n\nrun-name: "Auto QA"',
    '  group: auto-qa-smoke-${{ github.event.pull_request.number }}\n\nrun-name: "Auto QA smoke test (temporary)"',
  ],
  [
    "          ref: ${{ (github.event_name == 'pull_request' || github.event_name == 'pull_request_review' || github.event_name == 'pull_request_review_comment') && github.event.pull_request != null && github.event.pull_request.base.sha || github.sha }}",
    "          ref: 48fd16da2e737336e77742e4231ed738e05e7eaf",
  ],
  [
    "          fetch-depth: 1\n      - name: Save agent config folders for base branch restoration",
    "          fetch-depth: 1\n      - name: Verify the pinned workflow source and lock\n        shell: bash\n        run: |\n          sha256sum --check <<'SHA256'\n          d829c32a26860504ac3432fc2ec85fc930882bd32c4ef03870e99988910409f8  .github/workflows/auto-qa.md\n          b56046cc00b5404e1cb85c3e765a516b75508e15829491ee21c3fbed4c9a021f  .github/workflows/auto-qa.lock.yml\n          SHA256\n      - name: Save agent config folders for base branch restoration",
  ],
  [
    "    if: >\n      (github.event.label == null || github.event.label.name == 'auto-qa') && (((github.event.pull_request.state == 'open' &&",
    "    if: >\n      github.repository == 'canonical/snapcraft.io' &&\n      github.event.pull_request.number == 5974 &&\n      github.event.pull_request.head.ref == 'feat/auto-qa-pr-browser-checks' &&\n      github.event.label.name == 'auto-qa-smoke' && (((github.event.pull_request.state == 'open' &&",
  ],
];

test("smoke inputs match the immutable source revision 48fd16da2e737336e77742e4231ed738e05e7eaf", () => {
  assert.equal(
    hash(read("auto-qa.md")),
    "d829c32a26860504ac3432fc2ec85fc930882bd32c4ef03870e99988910409f8",
  );
  assert.equal(
    hash(normal),
    "b56046cc00b5404e1cb85c3e765a516b75508e15829491ee21c3fbed4c9a021f",
  );
});
test("the entire smoke harness has only the six explicit envelope changes", () => {
  let expected = normal;
  for (const [before, after] of changes) {
    assert.equal(expected.split(before).length, 2);
    expected = expected.replace(before, after);
  }
  assert.equal(harness, expected);
});
test("executing filename is a compiler lock identity", () => {
  assert.ok(harnessFile.endsWith(".lock.yml"));
});
test("agent, detector and safe outputs are byte-preserved", () => {
  const from = (text, start, end) => text.split(start)[1].split(end)[0];
  assert.equal(
    from(harness, "  agent:\n", "  conclusion:\n"),
    from(normal, "  agent:\n", "  conclusion:\n"),
  );
  assert.equal(
    from(harness, "  detection:\n", "  pre_activation:\n"),
    from(normal, "  detection:\n", "  pre_activation:\n"),
  );
  assert.equal(
    harness.split("  safe_outputs:\n")[1],
    normal.split("  safe_outputs:\n")[1],
  );
  assert.doesNotMatch(harness, /workflow_dispatch:|pull_request_target:/);
  assert.match(
    harness,
    /CLI_PROXY_IMAGE: 'ghcr\.io\/github\/gh-aw-mcpg:[^']+@sha256:[a-f0-9]{64}'/,
  );
});
